// Open-source licences (SET-07). The list is generated by `npm run licenses`.

import { useState } from 'react';
import { FlatList, Pressable, View } from 'react-native';

import { AppText } from '@/components/AppText';
import { Card } from '@/components/Card';
import { Icon } from '@/components/Icon';
import licenses from '@/content/licenses.json';
import { strings } from '@/content/strings';
import { useTheme } from '@/theme/ThemeProvider';

export function LicensesScreen() {
  const { colors, spacing } = useTheme();
  const [open, setOpen] = useState<string | null>(null);

  return (
    <FlatList
      data={licenses}
      keyExtractor={(item) => item.name}
      contentContainerStyle={{ padding: spacing.md, gap: spacing.sm }}
      ListHeaderComponent={
        <View style={{ gap: spacing.sm, marginBottom: spacing.sm }}>
          <AppText color="textMuted">{strings.licenses.intro}</AppText>
          <AppText variant="caption" color="textMuted">
            {strings.licenses.icons}
          </AppText>
        </View>
      }
      renderItem={({ item }) => {
        const expanded = open === item.name;
        return (
          <Card style={{ gap: spacing.sm }}>
            <Pressable
              onPress={() => setOpen(expanded ? null : item.name)}
              accessibilityRole="button"
              accessibilityState={{ expanded }}
              accessibilityLabel={`${item.name} ${item.version}, ${item.license}`}
              style={{ flexDirection: 'row', alignItems: 'center', gap: spacing.sm }}
            >
              <View style={{ flex: 1 }}>
                <AppText variant="bodyStrong">{item.name}</AppText>
                <AppText variant="caption" color="textMuted">
                  {`${item.version} · ${item.license}`}
                </AppText>
              </View>
              <Icon name={expanded ? 'expand_less' : 'expand_more'} color={colors.textMuted} />
            </Pressable>
            {expanded ? (
              <AppText variant="caption" selectable>
                {item.text || strings.licenses.noFile}
              </AppText>
            ) : null}
          </Card>
        );
      }}
    />
  );
}
